-- ----------------------------
-- Table structure for prf_flower
-- ----------------------------
DROP TABLE IF EXISTS `prf_flower`;
CREATE TABLE `prf_flower`  (
  `id` int NOT NULL,
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '花的名字',
  `des` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '花语',
  `from` tinyint NULL DEFAULT NULL COMMENT '0=升级解锁\n1=测试用\n2=活动获得\n3=鲜花礼包\r\n4=徐霞客处获得\r\n5=VIP专享\r\n6=公会获得\r\n7=敬请期待\n8=已绝版',
  `from_tip` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源提示',
  `index` int NULL DEFAULT NULL COMMENT '排序',
  `sell_res` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '出售获得的资源，类型,id,数量',
  `water` tinyint NULL DEFAULT NULL COMMENT '种植消耗的水滴',
  `cost` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培育所需资源',
  `cd` int NULL DEFAULT NULL COMMENT '培育所需时间',
  `qua` tinyint NULL DEFAULT NULL COMMENT '品质。1=绿色，2=蓝色，3=紫色，4=红色，5=金色',
  `charm` tinyint NULL DEFAULT NULL COMMENT '魅力值',
  `pic_0` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培育房-种子、收割-掉落的种子、鲜花升级-卡片种子',
  `pic_1` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '种地-刚刚播种',
  `pic_2` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '种地-长了一半',
  `pic_3` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '种地-完全长成、徐霞客、社团种植花盆内',
  `pic_4` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '收割-掉在地上',
  `pic_5` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '培育房-培育花台缩略图、仓库-缩略图、播种选择页、鲜花订单、插花、社团种植收取、好友交易、按住播种',
  `pic_6` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '花谱-外层显示、花市订单',
  `pic_7` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '花谱-带花瓶',
  `pic_land` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '土地图片',
  `spine_flower_land` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '种在地里的花动画',
  `spine_land` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '地块动画',
  `spine_flower_book` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图鉴花动画',
  `spine_flower_book_extra` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '图鉴花动画-附加',
  `no_bottle` tinyint NULL DEFAULT NULL COMMENT '不显示瓶子',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `from`(`from` ASC) USING BTREE,
  INDEX `qua`(`qua` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

