-- ----------------------------
-- Table structure for prf_flower_level
-- ----------------------------
DROP TABLE IF EXISTS `prf_flower_level`;
CREATE TABLE `prf_flower_level`  (
  `id` int NOT NULL,
  `flower` int NULL DEFAULT NULL COMMENT '花id',
  `level` int NULL DEFAULT 0 COMMENT '花-等级',
  `seed_up` int NULL DEFAULT NULL COMMENT '升到下级需要的种子，最大等级填-1',
  `coin_up` int NULL DEFAULT NULL COMMENT '升到下级需要的金币，最大等级填-1',
  `reap_exp` int NULL DEFAULT NULL COMMENT '收割经验',
  `reap_round` int NULL DEFAULT NULL COMMENT '收获次数',
  `reap_interval` int NULL DEFAULT NULL COMMENT '收获间隔',
  `seed_drop` int NULL DEFAULT NULL COMMENT '种子掉落数量',
  `seed_drop_rate` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '种子掉落概率，填100代表1%概率',
  `reap_cnt` int NULL DEFAULT NULL COMMENT '一次收获几个',
  `flower_min` int NULL DEFAULT NULL COMMENT '摘花保底数量',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `fl`(`flower` ASC, `level` ASC) USING BTREE,
  INDEX `idx_fl_cover`(`flower` ASC, `level` ASC, `reap_cnt` ASC, `flower_min` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of prf_flower_level
-- ----------------------------

-- ----------------------------
-- Table structure for prf_item
-- ----------------------------
DROP TABLE IF EXISTS `prf_item`;
CREATE TABLE `prf_item`  (
  `id` int NOT NULL,
  `ser` int NULL DEFAULT NULL COMMENT '道具系列',
  `type` int NULL DEFAULT 0 COMMENT '道具类型\r\n0 普通道具\r\n1 工厂道具\r\n2 转换器\r\n3 点击使用的道具\r\n4 拖拽到目标使用的道具',
  `cost` int NULL DEFAULT 0 COMMENT '工厂类型道具产出消耗的体力',
  `lv` int NULL DEFAULT NULL COMMENT '道具等级',
  `from` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '来源id',
  `name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '道具名称',
  `tips` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '道具介绍',
  `star` int NULL DEFAULT NULL COMMENT '该道具对应的绿星数量',
  `next` int NULL DEFAULT NULL COMMENT '合成道具id',
  `auto_drop` tinyint NULL DEFAULT 0 COMMENT '工厂是否自动产出道具',
  `need_open` tinyint NULL DEFAULT 0 COMMENT '是否需要等待开启',
  `cool_drop` int NULL DEFAULT NULL COMMENT '一次CD掉落个数',
  `cool_time` int NULL DEFAULT NULL COMMENT '冷却时间',
  `cool_maxnum` int NULL DEFAULT NULL COMMENT '冷却时间累积次数',
  `cool_money` int NULL DEFAULT NULL COMMENT '冷却加速花费钻石（最大值）',
  `sell` int NULL DEFAULT NULL COMMENT '出售价格-金币',
  `use` int NULL DEFAULT NULL COMMENT '可直接使用的道具，boxid',
  `die` int NULL DEFAULT 0 COMMENT '特殊-掉落完后变成什么\r\n<0 直接消失\r\n==0 进入cd\r\n>0 变成指定道具, 如果道具不存在也消失',
  `exp` int NULL DEFAULT NULL COMMENT '该等级道具合成下一级道具时是否会产出经验',
  `gold` int NULL DEFAULT NULL COMMENT '副本合成掉落金币',
  `rare` int NULL DEFAULT NULL COMMENT '0=普通，1=稀有（出售时跳出提醒框）',
  `tids` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '转换器内可投入物品的id',
  `count` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL DEFAULT NULL COMMENT '转换器内对应投入物品的数量 ',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `m`(`next` ASC) USING BTREE,
  INDEX `s`(`star` ASC) USING BTREE,
  INDEX `t`(`ser` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin ROW_FORMAT = DYNAMIC;

